<?php
declare(strict_types=1);
require __DIR__.'/../bootstrap.php';
use Ismile\App;use Ismile\Auth;use Ismile\Db;use Ismile\WorkshopCashSale;use Ismile\WorkshopTickets;use Ismile\UserError;
if(App::isLive()||!str_starts_with((string)App::config('db.name'),'ismile_workshop_test_real_')||App::config('payments.psoola.api_base')!=='http://127.0.0.1:8830')throw new RuntimeException('Isolated cash workshop fixture required.');
$passed=0;$check=static function(string $name,bool $ok)use(&$passed):void{if(!$ok)throw new RuntimeException('FAILED: '.$name);echo 'PASS: '.$name.PHP_EOL;$passed++;};
$reject=static function(callable $fn):bool{try{$fn();return false;}catch(UserError){return true;}};
$fixture=static fn(string $query=''):array=>json_decode(file_get_contents('http://127.0.0.1:8830/fixture'.$query),true);
$owner=Db::one("SELECT * FROM admin_users WHERE role='owner' LIMIT 1");
$staffId=Auth::createUser('cash-sale-staff@example.invalid','Cash Staff','registration',bin2hex(random_bytes(16)));Db::update('admin_users',['workshop_booking_access'=>1],'id=?',[$staffId]);$staff=Db::one('SELECT * FROM admin_users WHERE id=?',[$staffId]);
$seed=static function(string $suffix,string $status='paid'):array{$id=Db::insert('registrations',['ref'=>'PC'.strtoupper(bin2hex(random_bytes(5))),'first_name'=>'Paid','father_name'=>'Workshop','grandfather_name'=>$suffix,'email'=>'cash-sale-'.$suffix.'@example.invalid','phone'=>'+9647501234567','city'=>'Sulaimani','specialty'=>'gp','ticket_type'=>'professional','status'=>$status,'comp_reason'=>$status==='complimentary'?'Fixture':null,'view_nonce'=>bin2hex(random_bytes(16)),'created_at'=>App::now(),'updated_at'=>App::now(),'paid_at'=>App::now()]);return Db::one('SELECT * FROM registrations WHERE id=?',[$id]);};
$id='simplified-direct-veneers';$fixture('/stock?id='.$id.'&available=25');$price=(int)Db::value('SELECT price FROM workshops WHERE id=?',[$id]);Db::update('workshops',['display_price'=>100,'display_currency'=>'USD'],'id=?',[$id]);
$input=['workshop'=>$id,'cash_received'=>'1','cash_currency'=>'USD','cash_amount'=>'100.00'];$person=$seed('usd');$before=$fixture();$guestBefore=(int)Db::value('SELECT COUNT(*) FROM guest_workshop_orders');
$check('Cash must be explicitly received',$reject(fn()=>WorkshopCashSale::register($person,$staff,array_replace($input,['cash_received'=>'0']))));
$check('Wrong dollar amount is rejected before an order',$reject(fn()=>WorkshopCashSale::register($person,$staff,array_replace($input,['cash_amount'=>'99']))));
$check('Non-workshop staff cannot issue a paid workshop order',$reject(fn()=>WorkshopCashSale::register($person,['id'=>$staffId,'role'=>'viewer'],$input)));
$check('Unpaid or guest summit attendees cannot buy workshop tickets',$reject(fn()=>WorkshopCashSale::register($seed('cancelled','cancelled'),$staff,$input))&&$reject(fn()=>WorkshopCashSale::register($seed('guest','complimentary'),$staff,$input)));
$check('Failed validation creates no provider sale',count($fixture()['orders'])===count($before['orders']));
WorkshopCashSale::register($person,$staff,$input);$booking=Db::one('SELECT * FROM workshop_bookings WHERE registration_id=?',[$person['id']]);$receipt=Db::one('SELECT * FROM workshop_cash_receipts WHERE booking_id=?',[$booking['id']]);$order=Db::one('SELECT * FROM workshop_ticket_orders WHERE booking_id=?',[$booking['id']]);
$check('Dollar cash is saved as a paid IQD booking',$booking['payment_status']==='paid'&&$booking['paid_how']==='cash'&&(int)$booking['amount_paid']===$price&&(int)$booking['price_agreed']===$price);
$check('Original dollar receipt and conversion quote are preserved',$receipt['currency']==='USD'&&(int)$receipt['amount_minor']===10000&&(int)$receipt['quote_usd_minor']===10000&&(int)$receipt['amount_iqd']===$price);
$check('Cash immediately issues a verified paid PSOOLA order',$order['provider_status']==='paid'&&$order['currency']==='IQD'&&(int)$order['amount']===$price);
$body=json_decode($order['request_json'],true);$check('It issues a normal workshop ticket, not a guest ticket',!isset($body['isComplimentary'])&&(int)Db::value('SELECT COUNT(*) FROM guest_workshop_orders')===$guestBefore&&$body['items'][0]['quantity']===1);
$count=count($fixture()['orders']);WorkshopCashSale::register($person,$staff,$input);$check('Double submission reuses the original paid order',count($fixture()['orders'])===$count&&(int)Db::value('SELECT COUNT(*) FROM workshop_bookings WHERE registration_id=?',[$person['id']])===1);
$check('Another staff member cannot retry or change that receipt',$reject(fn()=>WorkshopTickets::issue((int)$booking['id'],['role'=>'registration','id'=>$staffId+1,'workshop_booking_access'=>1]))&&$reject(fn()=>WorkshopCashSale::register($person,$staff,array_replace($input,['cash_amount'=>'101']))));
$iqd=$seed('iqd');WorkshopCashSale::register($iqd,$owner,array_replace($input,['cash_currency'=>'IQD','cash_amount'=>(string)$price]));$iqdReceipt=Db::one('SELECT cr.* FROM workshop_cash_receipts cr JOIN workshop_bookings wb ON wb.id=cr.booking_id WHERE wb.registration_id=?',[$iqd['id']]);$check('Dinar cash is also preserved and issued in IQD',$iqdReceipt['currency']==='IQD'&&(int)$iqdReceipt['amount_minor']===$price&&(int)$iqdReceipt['amount_iqd']===$price);
$bad=$seed('wrong');$check('Incorrect IQD is rejected',$reject(fn()=>WorkshopCashSale::register($bad,$staff,array_replace($input,['cash_currency'=>'IQD','cash_amount'=>(string)($price-1)]))));
foreach(['0','-1','1e5','100.001','NaN'] as $amount)$check('Invalid cash amount rejected: '.$amount,$reject(fn()=>WorkshopCashSale::register($bad,$staff,array_replace($input,['cash_amount'=>$amount]))));
$check('IQD must be a whole amount',$reject(fn()=>WorkshopCashSale::register($bad,$staff,array_replace($input,['cash_currency'=>'IQD','cash_amount'=>$price.'.50']))));
$lost=$seed('lost');$check('Lost API response keeps a retryable receipt',$reject(fn()=>WorkshopCashSale::register($lost,$staff,$input)));
$lostBooking=Db::one('SELECT * FROM workshop_bookings WHERE registration_id=?',[$lost['id']]);$lostOrder=Db::one('SELECT * FROM workshop_ticket_orders WHERE booking_id=?',[$lostBooking['id']]);$lostCount=count($fixture()['orders']);
$check('Lost response preserves paid cash and original request key',$lostBooking['payment_status']==='paid'&&$lostOrder['provider_status']==='unknown'&&$lostOrder['idempotency_key']!=='');
WorkshopCashSale::register($lost,$staff,$input);$check('Retry after a lost response issues no duplicate provider sale',count($fixture()['orders'])===$lostCount&&Db::value('SELECT provider_status FROM workshop_ticket_orders WHERE booking_id=?',[$lostBooking['id']])==='paid');
Db::update('workshops',['display_price'=>null,'display_currency'=>null],'id=?',[$id]);$check('Missing saved USD price never invents an exchange rate',$reject(fn()=>WorkshopCashSale::register($bad,$staff,$input)));
$fixture('/stock?id='.$id.'&available=0');$check('Sold out workshop cannot create another cash sale',$reject(fn()=>WorkshopCashSale::register($bad,$staff,array_replace($input,['cash_currency'=>'IQD','cash_amount'=>(string)$price]))));
$beforeRetry=count($fixture()['orders']);WorkshopCashSale::register($person,$staff,$input);$check('Existing receipt remains retryable when sold out or quote changes',count($fixture()['orders'])===$beforeRetry);
$fixture('/stock?id='.$id.'&available=25');
$oldBooking=Db::one('SELECT * FROM workshop_bookings WHERE registration_id=?',[$iqd['id']]);Db::update('workshop_bookings',['removed_at'=>App::now(),'removed_by'=>$owner['id']],'id=?',[$oldBooking['id']]);$receiptCount=(int)Db::value('SELECT COUNT(*) FROM workshop_cash_receipts');
$check('Removing a local booking does not permit collecting the paid ticket twice',$reject(fn()=>WorkshopCashSale::register($iqd,$staff,array_replace($input,['cash_currency'=>'IQD','cash_amount'=>(string)$price])))&&(int)Db::value('SELECT COUNT(*) FROM workshop_cash_receipts')===$receiptCount);
Db::update('workshops',['display_price'=>100,'display_currency'=>'USD'],'id=?',[$id]);
echo $passed.' paid cash workshop checks passed.'.PHP_EOL;
